import React, { useMemo } from "react";

import ReactFlow, {
  Background,
  Controls,
  MiniMap,
  MarkerType,
} from "reactflow";

import "reactflow/dist/style.css";

import {
  workers,
  partitions,
  pipeline,
} from "../data/mockData";


function TopologyGraph() {

  /*
   * Generate topology nodes dynamically.
   *
   * The UI does NOT assume that there are 20 workers.
   * It renders however many workers/partitions exist
   * in mockData.js or eventually come from the API.
   */

  const nodes = useMemo(() => {

    const kafkaNode = {
      id: "kafka",
      type: "default",

      position: {
        x: 50,
        y: 250,
      },

      data: {
        label: `Kafka\n${partitions.length} Partitions`,
      },
    };


    const workerPoolNode = {
      id: "worker-pool",
      type: "default",

      position: {
        x: 400,
        y: 250,
      },

      data: {
        label: `Worker Pool\n${workers.length} Workers`,
      },
    };


    const stateNode = {
      id: "rocksdb",
      type: "default",

      position: {
        x: 800,
        y: 150,
      },

      data: {
        label: "RocksDB\nState Store",
      },
    };


    const metricsNode = {
      id: "prometheus",
      type: "default",

      position: {
        x: 800,
        y: 350,
      },

      data: {
        label: "Prometheus\nMetrics",
      },
    };


    /*
     * Generate partition nodes dynamically.
     *
     * We don't display every partition in the main graph
     * because large clusters would become unreadable.
     *
     * The worker pool represents the complete distributed
     * worker cluster.
     */

    const partitionNodes = partitions.map(
      (partition, index) => {

        const columns = 5;

        const column = index % columns;

        const row = Math.floor(index / columns);

        return {
          id: `partition-${partition.id}`,

          type: "default",

          position: {
            x: 200 + column * 105,
            y: 80 + row * 65,
          },

          data: {
            label: `P${String(partition.id).padStart(2, "0")}`,
          },
        };
      }
    );


    /*
     * Generate worker nodes dynamically.
     *
     * These are kept separate from the main pipeline
     * nodes so that we can later switch to an expandable
     * worker-cluster visualization.
     */

    const workerNodes = workers.map(
      (worker, index) => {

        const columns = 5;

        const column = index % columns;

        const row = Math.floor(index / columns);

        return {
          id: worker.id,

          type: "default",

          position: {
            x: 430 + column * 105,
            y: 80 + row * 65,
          },

          data: {
            label: worker.name,
          },
        };
      }
    );


    return [
      kafkaNode,
      workerPoolNode,
      stateNode,
      metricsNode,

      ...partitionNodes,
      ...workerNodes,
    ];

  }, []);


  /*
   * Generate the connections dynamically.
   */

  const edges = useMemo(() => {

    const baseEdges = [
      {
        id: "kafka-worker-pool",

        source: "kafka",

        target: "worker-pool",

        animated: true,

        markerEnd: {
          type: MarkerType.ArrowClosed,
        },
      },

      {
        id: "worker-pool-rocksdb",

        source: "worker-pool",

        target: "rocksdb",

        animated: true,

        markerEnd: {
          type: MarkerType.ArrowClosed,
        },
      },

      {
        id: "worker-pool-prometheus",

        source: "worker-pool",

        target: "prometheus",

        animated: true,

        markerEnd: {
          type: MarkerType.ArrowClosed,
        },
      },
    ];


    /*
     * Connect every partition to the worker responsible
     * for it.
     */

    const partitionEdges = partitions
      .filter(
        (partition) => partition.workerId
      )
      .map(
        (partition) => ({
          id: `partition-worker-${partition.id}`,

          source: `partition-${partition.id}`,

          target: partition.workerId,

          animated: false,
        })
      );


    return [
      ...baseEdges,
      ...partitionEdges,
    ];

  }, []);


  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      fitView
      fitViewOptions={{
        padding: 0.2,
      }}
      attributionPosition="bottom-left"
    >

      <Background
        gap={20}
        size={1}
      />

      <Controls />

      <MiniMap />

    </ReactFlow>
  );
}


export default TopologyGraph;
